const text = $input.first().json.text;

const regex = /```sql\s*\n([\s\S]*?)\n```/gi;
const sqlBlocks = [...text.matchAll(regex)].map(match => match[1].trim());

let sqlQueries = [];

sqlBlocks.forEach(block => {
  const queries = block.split(';')
    .map(q => q.trim())
    .filter(q => q.length > 0);

  sqlQueries.push(...queries.map(q => q + ';'));
});

return sqlQueries.map(query => ({
  json: {
    "Query": query
  }
}));
